$names=['coachHero','coachQualifications','coachPublication','coachTraining','coachVisit','coachTextItem'];$common=$modx->getObject(modCategory::class,['category'=>'Общие']);foreach($names as $name){$c=$modx->getObject(modChunk::class,['name'=>$name])?:$modx->newObject(modChunk::class);$c->fromArray(['name'=>$name,'category'=>$common->get('id'),'snippet'=>file_get_contents($root.'cms/chunks/'.$name.'.html')]);if(!$c->save())throw new RuntimeException('Coach chunk save failed');}
